const page = computed(() => definitions[route.name] || definitions.GDOverview)
const schemas = ref({}), role = ref(888), stats = ref({}), rows = ref([]), total = ref(0), active = ref(''), currentPage = ref(1), search = ref(''), filterStatus = ref(''), loading = ref(false), saving = ref(false)
const formOpen = ref(false), form = ref({}), formRef = ref(), editing = ref(0), options = ref({}), actionOpen = ref(false), chosenAction = ref({}), actionRow = ref({}), actionForm = ref({}), detailOpen = ref(false), detail = ref({})
