function date(v) { return v ? formatTimeToStr(v) : '—' }
function money(v, currency = 'CNY') { const raw = String(v || '0'); const sign = raw.startsWith('-') ? '-' : ''; const digits = raw.replace(/^-/, ''); const padded = currency === 'JPY' ? digits : digits.padStart(3, '0'); const whole = currency === 'JPY' ? padded : padded.slice(0, -2); return `${currency} ${sign}${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}${currency === 'JPY' ? '' : `.${padded.slice(-2)}`}` }
function percent(n, d) { if (n === null || n === undefined) return '观察中'; return d ? `${(n / d * 100).toFixed(1)}%` : '—' }
function display(v, field, row) { if (v === null || v === '' || v === undefined) return '—'; if (field.key.endsWith('Minor')) return money(v, row.currency); if (field.type === 'datetime' || field.key.endsWith('At')) return date(v); if (field.type === 'boolean') return v ? '开启' : '关闭'; return optionsLabel[v] || v }
function tagType(status) { return ['published', 'active', 'approved', 'paid', 'received', 'resolved', 'rewarded'].includes(status) ? 'success' : ['failed', 'rejected', 'revoked'].includes(status) ? 'danger' : ['pending', 'pending_review', 'attempted'].includes(status) ? 'warning' : 'info' }
function fieldLabel(key) { return schemas.value[active.value]?.fields.find(f => f.key === key)?.label || ({ id: 'ID', ownerId: '所属账号', userId: '用户账号', status: '状态', createdAt: '创建时间', updatedAt: '更新时间' })[key] || key }
async function load() { loading.value = true; try { if (!Object.keys(schemas.value).length) { const res = await api.schema(); if (res.code !== 0) return; schemas.value = Object.fromEntries(res.data.map(x => [x.key, x])); role.value = res.data[0]?.role || 888 } if (page.value.dashboard || page.value.analytics || page.value.revenue) { const res = await api.overview(); if (res.code === 0) stats.value = res.data } if (!active.value || !(page.value.resources.includes(active.value) || active.value === 'accounts' && page.value.accounts)) active.value = page.value.accounts ? 'accounts' : page.value.resources.find(k => schemas.value[k]) || ''; await loadRows() } finally { loading.value = false } }
async function loadRows() { if (!active.value) return; const requested = active.value; loading.value = true; try { if (active.value === 'accounts') { const res = await api.accounts(); if (res.code === 0 && requested === active.value) { rows.value = res.data.filter(u => !search.value || `${u.userName} ${u.nickName}`.includes(search.value)); total.value = rows.value.length } } else { const res = await api.records(active.value, { page: currentPage.value, pageSize: 20, search: search.value, status: filterStatus.value }); if (res.code === 0 && requested === active.value) { rows.value = res.data.list; total.value = res.data.total } } } finally { loading.value = false } }
function searchRecords() { currentPage.value = 1; loadRows() }
function switchTab() { search.value = ''; filterStatus.value = ''; currentPage.value = 1; loadRows() }
function canEdit(row) { return canCreate.value && !['orders', 'refunds', 'ads'].includes(active.value) && !(active.value === 'dramas' && !['draft', 'rejected', 'offline'].includes(row.status)) && !(['bills', 'settlements', 'compensations'].includes(active.value) && row.status !== 'draft') }
async function loadOptions(key, query = '') { const res = await api.records(key, { pageSize: 100, search: query }); if (res.code === 0) options.value[key] = res.data.list }
async function openForm(row) { editing.value = row?.id || 0; if (active.value === 'accounts') form.value = { username: '', password: '', nickName: '', role: 200 }; else { form.value = {}; for (const f of editableFields.value) form.value[f.key] = (f.type === 'number' || f.type === 'integer' ? (row?.[f.key] !== undefined ? Number(row[f.key]) : undefined) : row?.[f.key]) ?? (f.type === 'boolean' ? false : f.type === 'number' || f.type === 'integer' ? 0 : f.type === 'datetime' ? null : ''); const refs = [...new Set(editableFields.value.filter(f => f.ref && schemas.value[f.ref]).map(f => f.ref))]; await Promise.all(refs.map(async key => { const res = await api.records(key, { pageSize: 100 }); if (res.code === 0) options.value[key] = res.data.list })) } formOpen.value = true }
async function submitForm() { if (!(await formRef.value?.validate().catch(() => false))) return; saving.value = true; try { const res = active.value === 'accounts' ? await api.createAccount(form.value) : await api.saveRecord(active.value, form.value, editing.value); if (res.code === 0) { formOpen.value = false; ElMessage.success('已保存'); await load() } } finally { saving.value = false } }
function rowActions(row) { const st = row.status, key = active.value, out = []; const add = (key, label) => out.push({ key, label }); if (key === 'dramas' && role.value !== 200) { if (['draft', 'rejected', 'offline'].includes(st)) { add('submit', '提交审核'); add('batch', '批量创建单集'); } add('version', '保存内容版本'); if (st === 'pending_review' && role.value === 888) { add('approve', '审核通过'); add('reject', '审核拒绝'); } if (st === 'approved') add('publish', '发布'); if (st === 'published') add('offline', '下架'); } if (['plans', 'policies'].includes(key) && role.value === 888) { add(st === 'active' ? 'disable' : 'activate', st === 'active' ? '停用 / 下架' : '启用 / 上架') } if (key === 'plans' && role.value === 200) { add('buyMembership', '创建会员首购订单'); add('buyRenewal', '创建会员续费订单'); } if (['orders', 'refunds', 'ads', 'compensations', 'settlements'].includes(key) && role.value === 888 && ['pending', 'draft', 'attempted'].includes(st)) add('request', '提交凭据并申请审批'); if (key === 'orders' && st === 'paid' && role.value !== 300) add('refund', '申请退款'); if (key === 'approvals' && st === 'pending') add('decide', '审核申请'); if (key === 'feedback' && st !== 'resolved' && role.value === 888) add('resolve', '回复并处理'); if (key === 'alerts' && st !== 'resolved') add('resolve', '记录恢复并关闭告警'); if (key === 'bills' && st === 'draft' && role.value === 888) add('reconcile', '对账与差异处理'); if (key === 'ads' && st === 'attempted') add('fail', '标记广告失败'); if (key === 'favorites' || ['dramas', 'episodes', 'versions'].includes(key) && st === 'draft') { if (schemas.value[key]?.canWrite) add('delete', key === 'favorites' ? '取消收藏' : '删除草稿') } if (key === 'history') add('continue', '继续观看'); if (key === 'favorites') add('openDrama', '查看剧集'); return out }
async function openAction(row, item) { if (item.key === 'delete') { const confirmed = await ElMessageBox.confirm('确认删除这条记录？', '删除确认', { type: 'warning' }).then(() => true).catch(() => false); if (!confirmed) return; const res = await api.deleteRecord(active.value, row.id); if (res.code === 0) await loadRows(); return } if (item.key === 'continue') { const res = await api.playback(row.episodeId); if (res.code === 0) { const list = await api.records('dramas', { id: res.data.episode.dramaId }); const d = list.data?.list[0]; if (d) { await openDrama(d); await playEpisode(res.data.episode) } else ElMessage.info('剧集未上架或授权已过期') } return } if (item.key === 'openDrama') { const list = await api.records('dramas', { id: row.dramaId }); const d = list.data?.list[0]; if (d) await openDrama(d); else ElMessage.info('剧集未上架或授权已过期'); return } actionRow.value = row; chosenAction.value = item; actionForm.value = { action: item.key, note: '', evidence: '', decision: true, start: 1, count: 1 }; actionOpen.value = true }
async function submitAction() { saving.value = true; try { let res; const k = chosenAction.value.key; if (k === 'buyMembership' || k === 'buyRenewal') res = await api.saveRecord('orders', { kind: k === 'buyRenewal' ? 'renewal' : 'membership', planId: actionRow.value.id, provider: actionRow.value.platform }); else if (k === 'refund') res = await api.saveRecord('refunds', { orderId: actionRow.value.id, reason: actionForm.value.note }); else res = await api.action(active.value, actionRow.value.id, actionForm.value); if (res.code === 0) { actionOpen.value = false; ElMessage.success(k.startsWith('buy') ? '已创建待支付订单，可在钱包和订单中查看' : '操作已记录'); await load() } } finally { saving.value = false } }
function showDetail(row) { detail.value = row; detailOpen.value = true }
async function upload(event) { const file = event.target.files[0]; if (!file) return; saving.value = true; try { const res = await api.importBills(file); if (res.code === 0) { ElMessage.success(`已导入 ${res.data.imported} 行`); await load() } } finally { event.target.value = ''; saving.value = false } }
async function runPreview() { const res = await api.preview(previewForm.value); if (res.code === 0) previewResult.value = res.data }
async function openDrama(drama) { stopPlayback(); selectedDrama.value = drama; selectedEpisode.value = null; playInfo.value = {}; const res = await api.records('episodes', { dramaId: drama.id, pageSize: 100 }); if (res.code === 0) { const extra = await Promise.all(Array.from({ length: Math.max(0, Math.ceil(res.data.total / 100) - 1) }, (_, i) => api.records('episodes', { dramaId: drama.id, pageSize: 100, page: i + 2 }))); dramaEpisodes.value = [...res.data.list, ...extra.flatMap(x => x.code === 0 ? x.data.list : [])].sort((a, b) => a.number - b.number); dramaOpen.value = true } }
async function favorite() { const res = await api.saveRecord('favorites', { dramaId: selectedDrama.value.id }); if (res.code === 0) ElMessage.success('已收藏') }
async function playEpisode(ep) { stopPlayback(); selectedEpisode.value = ep; sessionId.value = CreateUUID(); const res = await api.playback(ep.id); if (res.code === 0) playInfo.value = res.data }
async function buyEpisode() { const res = await api.saveRecord('orders', { kind: 'episode', episodeId: selectedEpisode.value.id, provider: 'web' }); if (res.code === 0) ElMessage.success('已创建待支付订单，请前往钱包和订单查看') }
async function attemptAd() { const res = await api.saveRecord('ads', { episodeId: selectedEpisode.value.id, network: 'web', placement: 'episode_unlock' }); if (res.code === 0) ElMessage.info('广告尝试已记录；接入广告平台后才能展示广告并验证发奖') }
async function event(type, watched = 0, bufferMs = 0) { if (!selectedEpisode.value || role.value !== 200) return; await api.trackEvent({ episodeId: selectedEpisode.value.id, event: type, source: 'discover', sessionId: sessionId.value, bufferMs, positionSeconds: Math.floor(videoRef.value?.currentTime || 0), watchedSeconds: watched, startupMs: type === 'play' && playingSince ? Math.max(0, Date.now() - playingSince) : 0, errorCode: type === 'error' ? String(videoRef.value?.error?.code || 'unknown') : '' }) }
function onPlaybackRequested() { playingSince = Date.now() }
function onWaiting() { if (!bufferingSince) bufferingSince = Date.now() }
function onPlay() { if (bufferingSince) { event('buffer', 0, Date.now() - bufferingSince); bufferingSince = 0 } if (!progressTimer) { event('play'); lastPosition = Math.floor(videoRef.value?.currentTime || 0); progressTimer = setInterval(() => { const current = Math.floor(videoRef.value?.currentTime || 0); if (!videoRef.value?.paused && current > lastPosition) event('progress', Math.min(30, current - lastPosition)); lastPosition = current }, 30000) } }
function onEnd() { event('complete', Math.max(0, Math.min(30, Math.floor(videoRef.value?.currentTime || 0) - lastPosition))); clearInterval(progressTimer); progressTimer = null }
function onVideoError() { event('error') }
function stopPlayback() { clearInterval(progressTimer); progressTimer = null; bufferingSince = 0; videoRef.value?.pause(); playingSince = Date.now() }
onBeforeUnmount(stopPlayback)
watch(() => route.name, () => { active.value = ''; currentPage.value = 1; search.value = ''; filterStatus.value = ''; rows.value = []; load() }, { immediate: true })
</script>

